-- Infernal Relay (Hellfire) - Remove the homebrew starting wave
-- Added in 2019 to "spawn an initial wave of daemons, so the battle can begin at once when the player enters the area".
-- It fires once on SMART_EVENT_JUST_CREATED, so the wave only exists for the first 10 minutes after a server start,
-- lands two Wrath Masters (19005) inside the defender line instead of marching down from the ridge, and never repeats.
DELETE FROM `smart_scripts` WHERE (`source_type` = 0 AND `entryorguid` IN (-68744, -68745));
UPDATE `creature_template` SET `AIName` = '' WHERE (`entry` = 19215);
UPDATE `creature` SET `Comment` = 'SAI Target' WHERE (`id` = 19215) AND (`guid` IN (68744, 68745));

-- Infernal Target (Hyjal) - Keep the two launch points airborne
-- Both spawns sit at z 79.5 / 91.9 over a floor near 41.7. `creature_template_movement` allows ground movement only,
-- so Creature::UpdateMovementFlags clears gravity-disable and drops them onto the stairs.
-- Maintainer note: These are hacks, but we'd otherwise need cpp for a miniscule thing. So whatever.
DELETE FROM `creature_movement_override` WHERE (`SpawnId` IN (74081, 74082));
INSERT INTO `creature_movement_override` (`SpawnId`, `Ground`, `Swim`, `Flight`, `Rooted`, `Chase`, `Random`, `InteractionPauseTimer`) VALUES
(74081, NULL, NULL, 1, NULL, NULL, NULL, NULL),
(74082, NULL, NULL, 1, NULL, NULL, NULL, NULL);

-- Pit Commander - Combat spells and the infernal barrage
-- Sniffed sequence: the Pit Commander casts 33393 Summon Infernals, then 0.4-1.2 s later both Infernal Target (Hyjal)
-- appear and cast 33240 Infernal in the same packet. The missile flies ~3.3 s and triggers 33636, summoning an
-- Infernal Siegebreaker (18946) at the impact point for 75 s. Linking the two Set Data rows to the cast keeps the
-- pair in step - the old 6 s / 7 s openers on independent 60 s timers drifted away from the cast that motivates them.
DELETE FROM `smart_scripts` WHERE (`source_type` = 0 AND `entryorguid` = 18945);
