-- Infernal Relay (Hellfire) - Sniffed positions and wander
-- Both relays are permanent spawns (every sighting in the corpus is a CreateObject1) and both wander: 5823 movement
-- points over 232 guid-sniff rows, single-hop segments with pauses and no splines. The infernal lands wherever the
-- relay happens to be standing, which is what scatters the barrage instead of cratering the same two spots.
UPDATE `creature` SET `position_x` = -261.12, `position_y` = 1095.94, `position_z` = 41.717, `MovementType` = 1, `wander_distance` = 10, `CreateObject` = 1, `VerifiedBuild` = 68887 WHERE (`id` = 19215) AND (`guid` = 68744);
UPDATE `creature` SET `position_x` = -242.51, `position_y` = 1095.53, `position_z` = 41.722, `MovementType` = 1, `wander_distance` = 10, `CreateObject` = 1, `VerifiedBuild` = 68887 WHERE (`id` = 19215) AND (`guid` = 68745);
